{"content":"// WP-F run49 §6.4 fixture regression (fresh script, in-memory store only).
// Exercises the repo's own createFleetModelSnapshotStore + fleetRunnerRecord.
// No live state touched: filePath:null, no HTTP, no engine-dir writes.
import { createFleetModelSnapshotStore } from "/home/[REDACTED]/.kainbain/runner-work/kb-8c7e2d15-3f17-41a1-b905-99ca5e536c83/api/flow/dispatch/fleetModelSnapshot.js";
import { NEW_MODEL_ID, fleetRunnerRecord } from "/home/[REDACTED]/.kainbain/runner-work/kb-8c7e2d15-3f17-41a1-b905-99ca5e536c83/api/flow/dispatch/fleetModelFixtures.mjs";

const AT = 1795000000000;
const confirmed = (over = {}) =>
  fleetRunnerRecord({
    runnerId: "wpf-r49-box",
    capabilities: {
      modelProvenance: { [NEW_MODEL_ID]: { harnesses: ["muse"], atMs: AT, source: "discovered" } },
      discoveryStatus: { muse: { ok: true, count: 1, atMs: AT } },
    },
    ...over,
  });

let pass = 0;
const check = (name, cond) => {
  console.log((cond ? "PASS" : "FAIL") + " " + name);
  if (cond) pass += 1;
  else process.exitCode = 1;
};

const store = createFleetModelSnapshotStore({ filePath: null, now: () => AT });

// 1-3: advertised -> present, count 1, harness-len 1
store.update([confirmed()]);
let snap = store.read();
let row = snap.models.find((m) => m.id === NEW_MODEL_ID);
check("1 advertised-present", !!row);
check("2 advertised-count-1", row?.runnerCount === 1);
check("3 advertised-harness-len-1", Array.isArray(row?.harnesses) && row.harnesses.length === 1);

// 4-6: dropped from leg -> row stays at 0 runners, unverified
store.update([confirmed({ capabilities: { models: [], modelProvenance: {}, discoveryStatus: { muse: { ok: true, count: 0, atMs: AT + 1 } } } })]);
snap = store.read();
row = snap.models.find((m) => m.id === NEW_MODEL_ID);
check("4 drop-row-persists", !!row);
check("5 drop-count-0", row?.runnerCount === 0);
check("6 drop-unverified", row?.verified === false && row?.available === false);

// 7-9: admin remove -> true, then false, then gone
check("7 remove-true", store.remove(NEW_MODEL_ID) === true);
check("8 remove-again-false", store.remove(NEW_MODEL_ID) === false);
snap = store.read();
check("9 remove-gone", !snap.models.some((m) => m.id === NEW_MODEL_ID));

// 10: re-advertise -> back at count 1
store.update([confirmed()]);
snap = store.read();
row = snap.models.find((m) => m.id === NEW_MODEL_ID);
check("10 re-advertise-back", !!row && row.runnerCount === 1);

// 11-12: bare id -> quarantined, never in models
store.update([
  confirmed({
    capabilities: {
      models: ["baremodel"],
      modelProvenance: {},
      discoveryStatus: { muse: { ok: true, count: 1, atMs: AT + 2 } },
    },
  }),
]);
snap = store.read();
check("11 bare-quarantined", snap.quarantined.some((q) => q.id === "baremodel"));
check("12 bare-never-in-models", !snap.models.some((m) => m.id === "baremodel"));

console.log(`\n${pass}/12 checks passed`);
